import { createPopState } from '../app/dgn-pop.js';
import { dgnBadgePath, dgnDisplaySymbol, DGN_COLORS } from '../app/dgn-traits.js';
import { sfxDgnPop, stopDgnPops } from '../app/jackpot-sfx.js';

const name = (q, t) => t ? `${DGN_COLORS[t.col]} ${dgnDisplaySymbol(q, t.sym, t.col)}` : 'unavailable';

/** Shared by every Degenerette source. Covered house art/labels are not mounted. */
export function mountPopBoards(host, rows, {
  hero = null, availableCount = rows.length, onChange = () => {}, onRevealAll = () => {},
} = {}) {
  const doc = host.ownerDocument || document;
  const state = createPopState(rows, hero);
  const cleanups = [];
  let disposed = false;
  let locked = false;
  let available = Math.min(rows.length, availableCount);
  const el = (tag, cls, text) => {
    const node = doc.createElement(tag);
    node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  };
  const listen = (node, fn) => {
    node.addEventListener('click', fn);
    cleanups.push(() => node.removeEventListener('click', fn));
  };
  const badge = (q, trait, cls) => {
    const img = el('img', cls);
    img.src = dgnBadgePath(q, trait.sym, trait.col);
    img.alt = '';
    img.draggable = false;
    return img;
  };
  const root = el('section', 'dgn-pop');
  const tally = el('div', 'dgn-pop__tally');
  tally.appendChild(el('span', 'dgn-pop__score-label', 'SCORE'));
  const total = el('strong', 'dgn-pop__score', '0');
  total.setAttribute('role', 'status');
  total.setAttribute('aria-live', 'polite');
  total.setAttribute('aria-atomic', 'true');
  tally.appendChild(total);
  root.appendChild(tally);
  const hint = el('p', 'dgn-pop__hint', 'Tap a quadrant · Flame reveals board');
  root.appendChild(hint);
  const grid = el('div', 'dgn-pop__grid');
  root.appendChild(grid);
  const cards = state.boards.map((board, index) => {
    const card = el('article', 'dgn-pop__card');
    const ticket = el('div', 'dgn-pop__ticket');
    const cells = board.quadrants.map((quadrant, q) => {
      const cell = el('button', `dgn-pop__cell dgn-pop__cell--q${q}`);
      cell.type = 'button';
      cell.setAttribute('aria-label', `Board ${index + 1}, ${name(q, quadrant.player)}${quadrant.hero ? ', Hero' : ''}. Reveal quadrant`);
      cell.appendChild(badge(q, quadrant.player, 'dgn-pop__badge'));
      if (quadrant.hero) cell.appendChild(el('span', 'dgn-pop__hero', 'HERO'));
      listen(cell, event => { event.stopPropagation(); reveal(index, 1 << q); });
      ticket.appendChild(cell);
      return cell;
    });
    const flame = el('button', 'dgn-pop__flame');
    flame.type = 'button';
    flame.setAttribute('aria-label', `Reveal this board (${index + 1})`);
    const mark = el('img', '');
    mark.src = '/whitepaper/flame-center.svg';
    mark.alt = '';
    flame.appendChild(mark);
    listen(flame, event => { event.stopPropagation(); reveal(index); });
    ticket.appendChild(flame);
    card.appendChild(ticket);
    card.appendChild(el('span', 'dgn-pop__number', `BOARD ${index + 1}`));
    const gold = el('span', 'dgn-pop__gold-total');
    gold.hidden = true;
    card.appendChild(gold);
    grid.appendChild(card);
    return { card, ticket, cells, flame, gold };
  });
  const all = el('button', 'dgn-pop__all', 'REVEAL ALL');
  all.type = 'button';
  listen(all, event => { event.stopPropagation(); revealAll(); });
  root.appendChild(all);
  host.appendChild(root);

  function paint(added = []) {
    const next = state.snapshot();
    const oldScore = Number(total.textContent);
    total.textContent = String(next.score);
    if (added.length && oldScore !== next.score) {
      total.getAnimations?.().forEach(animation => animation.cancel());
      if (!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
        total.animate?.([{ transform: 'scale(1.12)' }, { transform: 'scale(1)' }], { duration: 180 });
      }
    }
    for (const item of added) {
      const cell = cards[item.board].cells[item.quadrant];
      cell.textContent = '';
      cell.classList.add('is-open');
      if (item.points != null) cell.dataset.points = String(item.points);
      if (item.house) cell.appendChild(badge(item.quadrant, item.house, 'dgn-pop__badge'));
      else cell.appendChild(el('span', 'dgn-pop__unknown', '?'));
      cell.appendChild(badge(item.quadrant, item.player, 'dgn-pop__player'));
      if (item.hero) cell.appendChild(el('span', 'dgn-pop__hero', 'HERO'));
      if (item.points > 0) {
        const increment = el('span', 'dgn-pop__increment', `+${item.points}`);
        increment.setAttribute('aria-hidden', 'true');
        cell.appendChild(increment);
      }
      if (item.gold) {
        cell.classList.add('is-gold');
        cell.appendChild(el('span', 'dgn-pop__gold', 'GOLD MATCH'));
      }
      const matches = [item.symbolMatch ? 'symbol match' : '', item.colorMatch ? 'color match' : ''].filter(Boolean).join(', ');
      const detail = `Board ${item.board + 1}. You: ${name(item.quadrant, item.player)}. House: ${name(item.quadrant, item.house)}. ${matches || 'No match'}. ${item.hero ? 'Hero. ' : ''}${item.points == null ? 'Recorded score added when board completes.' : `${item.points} points.`}${item.gold ? ' Gold match.' : ''}`;
      cell.setAttribute('aria-label', detail);
      cell.title = detail;
    }
    cards.forEach((card, i) => {
      card.card.hidden = i >= available;
      card.flame.disabled = locked || next.masks[i] === 15;
      card.cells.forEach((cell, q) => {
        // Keep opened quadrants keyboard-inspectable, with idempotent activation.
        cell.disabled = locked;
        cell.setAttribute('aria-disabled', String(locked || Boolean(next.masks[i] & (1 << q))));
      });
      const goldCount = state.boards[i].quadrants.filter((q, j) => q.gold && (next.masks[i] & (1 << j))).length;
      card.gold.hidden = goldCount === 0;
      card.gold.textContent = state.boards[i].legacy
        ? `${goldCount} GOLD MATCH${goldCount === 1 ? '' : 'ES'}`
        : `GOLD ×${(1 + goldCount / 4).toFixed(2)}`;
    });
    grid.dataset.size = String(available === 1 ? 1 : available <= 4 ? 4 : 9);
    all.hidden = next.complete || rows.length === 1;
    all.disabled = locked;
    hint.textContent = next.complete ? 'All boards revealed' : 'Tap a quadrant · Flame reveals board';
    return next;
  }
  function commit(added) {
    if (!added.length) return;
    const next = paint(added);
    sfxDgnPop({ points: Math.max(0, ...added.map(q => q.points || 0)), gold: added.some(q => q.gold), count: added.length });
    onChange(next);
  }
  function reveal(index, mask = 15) {
    if (disposed || locked || index >= available) return;
    commit(state.reveal(index, mask));
  }
  function revealAll() {
    if (disposed || locked) return;
    onRevealAll();
    commit(cards.flatMap((_, i) => i < available ? state.reveal(i) : []));
  }
  paint();
  return {
    element: root, snapshot: state.snapshot, reveal, revealAll,
    setAvailableCount(count) { available = Math.min(rows.length, count); paint(); },
    setLocked(value) { locked = Boolean(value); paint(); },
    dispose() {
      disposed = true;
      cleanups.forEach(fn => fn());
      root.getAnimations?.({ subtree: true }).forEach(animation => animation.cancel());
      stopDgnPops();
    },
  };
}
